edits:
    id 'net.neoforged.moddev' version '2.0.148'
// The native addon can be compiled without loading TFC. Runtime NEVER substitutes for it.
def requestedLaunch = gradle.startParameter.taskNames.any { it.tokenize(':').last() in ['runClient', 'runServer'] }
def nativeRuntime = modRuntimeTests || requestedLaunch || providers.gradleProperty('nativeRuntime').map { it.toBoolean() }.getOrElse(false)
if (nativeRuntime) {
    apply from: 'tools/native-runtime.gradle'
    verifyNativeRuntimeJar(file("libs/${project.tfc_jar}"), 'tfc', project.minecraft_version)
    verifyNativeRuntimeJar(file("libs/${project.framework_jar}"), 'foundations_framework', project.minecraft_version)
    mavenCentral()
        content { includeGroup 'vazkii.patchouli'; includeGroup 'mezz.jei'; includeGroup 'net.mezzdev.config' }
    // 26.1.2 is unobfuscated. No 1.21.1 Parchment coordinates or mappings are applied.
    // Loaded only for explicitly requested native runtime validation. Never use old 1.21.1 artifacts.
    if (nativeRuntime) {
        localRuntime files("libs/${project.tfc_jar}", "libs/${project.framework_jar}")
        localRuntime "vazkii.patchouli:patchouli-neoforge:${patchouli_version}"
        localRuntime "mezz.jei:jei-${minecraft_version}-neoforge:${jei_version}"
        if (modRuntimeTests) {
            testRuntimeOnly files("libs/${project.tfc_jar}", "libs/${project.framework_jar}")
            testRuntimeOnly "vazkii.patchouli:patchouli-neoforge:${patchouli_version}"
            testRuntimeOnly "mezz.jei:jei-${minecraft_version}-neoforge:${jei_version}"
        }
    testImplementation 'org.ow2.asm:asm-tree:9.8'
    useJUnitPlatform {
        if (modRuntimeTests) excludeTags 'model-only'
        else excludeTags 'tfc-runtime'
    }
tasks.withType(JavaCompile).configureEach {
    options.encoding = 'UTF-8'
    // String-target Mixins bind to genuine native TFC at runtime. No synthetic target classes.
    options.compilerArgs.add('-proc:none')
}
    description = 'Native model/storage microbenchmark; not a live-server TPS test.'
    enabled = !modRuntimeTests

